-- HireSense AI: schema + sample (testing) data for MySQL
-- Import with:  mysql -u root -p < database/sample-data.sql
-- (The app creates the same tables itself and adds the admin login on first run;
--  importing this file just loads the sample jobs/candidates/interviews up front.
--  Importing it twice creates duplicates.)

CREATE DATABASE IF NOT EXISTS hireai;
USE hireai;

CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS jobs (id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, location VARCHAR(150), description TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS candidates (
  id INT AUTO_INCREMENT PRIMARY KEY, job_id INT NOT NULL, file_name VARCHAR(255), name VARCHAR(150), email VARCHAR(150), phone VARCHAR(50),
  title VARCHAR(150), location VARCHAR(150), years_exp DECIMAL(4,1) DEFAULT 0, score INT DEFAULT 0, skills_score INT DEFAULT 0,
  experience_score INT DEFAULT 0, domain_score INT DEFAULT 0, education_score INT DEFAULT 0, skill_overlap JSON, reasons JSON, strengths JSON,
  summary TEXT, recommendation VARCHAR(20), status VARCHAR(20) DEFAULT 'Review', resume_text MEDIUMTEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (job_id) REFERENCES jobs(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS candidate_ai (
  candidate_id INT NOT NULL, kind VARCHAR(20) NOT NULL, data JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (candidate_id, kind), FOREIGN KEY (candidate_id) REFERENCES candidates(id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS interviews (
  id INT AUTO_INCREMENT PRIMARY KEY, candidate_id INT NOT NULL, scheduled_at DATETIME NOT NULL, duration INT DEFAULT 45,
  mode VARCHAR(30) DEFAULT 'Video call', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (candidate_id) REFERENCES candidates(id) ON DELETE CASCADE
);

